import { createContext, createEffect, on, useContext } from "solid-js";
import { createMutable, modifyMutable, reconcile } from "solid-js/store";

import {
	GameSetupParametersModel,
	ReactiveGameSetupParameter,
} from "#core/ui-next/screens/create-game/game-parameters-model.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";

const parameters = [
	"Difficulty",
	"GameSpeeds",
	"Map",
	"MapSize",
	"AgeTransitionSetting",
	"GameStartCivSelectionMode",
	"LeaderAssociatedCivSelectionMode",
] as const;

export interface GameSetupOptionInfo {
	value: GameSetupParameterValue;
	name: string;
	icon: string;
	description: string;
}

export interface GameSetupOption {
	paramName: string;
	name: string;
	options: GameSetupOptionInfo[];
	selectedOption: GameSetupOptionInfo | undefined;

	value: GameSetupParameterValue;
	setValue: (value: GameSetupParameterValue) => void;
}

export type GameSetupModel = Record<(typeof parameters)[number], GameSetupOption>;

export function buildGameSetupModel() {
	const gameSetupModel = GameSetupParametersModel.get();

	const mapIcons = new Map<string, string>([
		["LOC_MAP_CONTINENTS_VORONOI_NAME", "MapTypes_ContinentsAndIslands"],
		["LOC_MAP_PANGAEA_VORONOI_NAME", "MapTypes_Pangaea_Islands"],
		["LOC_MAP_FRACTAL_VORONOI_NAME", "MapTypes_FractalContinents"],
		["LOC_MAP_SHATTERED_SEAS_NAME", "MapTypes_ShatteredSeas"],
		["LOC_MAP_CONTINENTS_NAME", "MapTypes_Continents"],
		["Everything", "MapTypes_Everything"],
		["Flat Lands", "MapTypes_FlatLands"],
		["LOC_MAP_CONTINENTS_PLUS_NAME", "MapTypes_ContinentsPlus"],
		["LOC_MAP_SHUFFLE_NAME", "MapTypes_Shuffle"],
		["LOC_MAP_ARCHIPELAGO_NAME", "MapTypes_Archipelago"],
		["LOC_MAP_ARCHIPELAGO_VORONOI_NAME", "MapTypes_Archipelago"],
		["LOC_MAP_FRACTAL_NAME", "MapTypes_Fractal"],
		["LOC_MAP_TERRA_INCOGNITA_NAME", "MapTypes_TerraIncognita"],
		["LOC_MAP_PANGAEA_PLUS_NAME", "MapTypes_PangeaPlus"],
		["Pangea", "MapTypes_Pangea"],
	]);

	const model = {};

	function createValue(domainValue: GameSetupDomainValue): GameSetupOptionInfo {
		const value = domainValue.value as string;
		const name = GameSetup.resolveString(domainValue.name) ?? "";
		const icon = `url('blp:${mapIcons.get(name) ?? ""}.png')`;
		const description = GameSetup.resolveString(domainValue.description) ?? "";

		return { value, name, icon, description };
	}

	function createOption(paramName: string, parameter: ReactiveGameSetupParameter): GameSetupOption {
		const name = GameSetup.resolveString(parameter.name) ?? "";
		const options = parameter.domain.possibleValues?.map((v) => createValue(v)) ?? [];
		const value = (parameter.value.value as string) || "";
		const activeOption = options.find((o) => o.value == value);
		const selectedOption = activeOption ? { ...activeOption } : undefined;
		const setValue = (value: GameSetupParameterValue) => parameter.setValue(value);

		return { paramName, name, value, options, selectedOption, setValue };
	}

	for (const paramName of parameters) {
		const parameter = gameSetupModel[paramName];
		const option = createOption(paramName, parameter);
		const mutableOption = createMutable(option);
		// eslint-disable-next-line solid/reactivity
		(model as GameSetupModel)[paramName] = mutableOption;

		createEffect(
			on(
				() => [parameter, parameter?.value],
				() => {
					const optionUpdate = createOption(paramName, parameter);
					modifyMutable(mutableOption, reconcile(optionUpdate));
				},
			),
		);
	}

	return model as GameSetupModel;
}

export const GameSetupModel = ModelRegistry.register(
	"GameSetupModel",
	ModelLifecycle.SharedInstance,
	buildGameSetupModel,
);

export const GameSetupModelContext = createContext<GameSetupModel>();

export function useGameSetupModelContext() {
	const context = useContext(GameSetupModelContext);

	if (!context) {
		throw new Error("useGameSetupModelContext: Cannot find context!");
	}

	return context;
}
